<?php require '_menu.php'; require_perm('audit'); $f = trim($_GET['q'] ?? '');
$rows = $f ? q('SELECT * FROM audit_log WHERE action LIKE ? OR username LIKE ? OR detail LIKE ? ORDER BY id DESC LIMIT 300', ["%$f%", "%$f%", "%$f%"])->fetchAll() : q('SELECT * FROM audit_log ORDER BY id DESC LIMIT 300')->fetchAll();
app_top('Audit log', $menu, $area); ?><h1>Audit log</h1><p class="mini">Every login, failed login, score entry, password change, payroll action and denied access is recorded here (latest 300).</p>
<form class="f" style="max-width:420px;margin-bottom:16px"><div class="row" style="grid-template-columns:1fr auto"><input name="q" value="<?= e($f) ?>" placeholder="Search user or action"><button class="btn">Search</button></div></form>
<div class="tw scroll"><table><thead><tr><th>When</th><th>User</th><th>Action</th><th>Detail</th><th>IP</th></tr></thead><tbody><?php foreach ($rows as $r) echo '<tr><td>' . date('j M Y, g:i a', strtotime($r['created_at'])) . '</td><td>' . e($r['username']) . '</td><td>' . e($r['action']) . '</td><td>' . e($r['detail']) . '</td><td>' . e($r['ip']) . '</td></tr>'; if (!$rows) echo '<tr><td colspan="5">Nothing logged yet.</td></tr>'; ?></tbody></table></div><?php app_bottom();
